import random
from itertools import combinations

def has_short_cycle(adj, n, max_len=5):
    # BFS from each vertex to find cycles of length <= max_len
    # Check girth >= 6 means no cycle of length 3, 4, or 5
    for s in range(n):
        # BFS with parent tracking
        dist = {s: 0}
        parent = {s: -1}
        queue = [s]
        while queue:
            new_queue = []
            for u in queue:
                if dist[u] >= max_len: continue
                for v in adj[u]:
                    if v == parent[u]: continue
                    if v in dist:
                        # found cycle of length dist[u] + dist[v] + 1
                        if dist[u] + dist[v] + 1 <= max_len:
                            return True
                    else:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        new_queue.append(v)
            queue = new_queue
    return False

def girth_at_least_6(edges, n):
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # Check no cycles of length 3,4,5
    # For each edge, temporarily remove it, check if BFS distance between endpoints is < 5
    for u,v in edges:
        adj[u].discard(v)
        adj[v].discard(u)
        # BFS from u, find distance to v
        dist = {u: 0}
        queue = [u]
        found_dist = None
        while queue:
            new_queue = []
            for x in queue:
                if dist[x] >= 4: continue
                for y in adj[x]:
                    if y not in dist:
                        dist[y] = dist[x] + 1
                        if y == v:
                            found_dist = dist[y]
                            break
                        new_queue.append(y)
                if found_dist is not None: break
            if found_dist is not None: break
            queue = new_queue
        adj[u].add(v)
        adj[v].add(u)
        if found_dist is not None and found_dist + 1 < 6:
            return False
    return True

def try_build(n=23, seed=0):
    random.seed(seed)
    adj = [set() for _ in range(n)]
    deg = [0]*n
    # try to build up to degree 4, girth >= 6
    # candidate edges
    all_pairs = list(combinations(range(n), 2))
    random.shuffle(all_pairs)
    edges = []
    for u,v in all_pairs:
        if deg[u] >= 4 or deg[v] >= 4: continue
        if v in adj[u]: continue
        # check adding (u,v) doesn't create cycle of length < 6
        # i.e., current distance u to v in graph should be >= 5
        # BFS
        dist = {u: 0}
        queue = [u]
        ok = True
        while queue:
            new_queue = []
            for x in queue:
                if dist[x] >= 4: continue
                for y in adj[x]:
                    if y not in dist:
                        dist[y] = dist[x]+1
                        new_queue.append(y)
            queue = new_queue
        if v in dist and dist[v] < 5:
            continue
        adj[u].add(v); adj[v].add(u)
        deg[u]+=1; deg[v]+=1
        edges.append((u,v))
    # Check min degree >= 3
    if min(deg) >= 3:
        return edges, deg
    return None

